      const ramjet = S.armed && inGate;
      const burner = !ramjet && inGate && S.battery > 0;
      S.mode = ramjet ? 'ramjet' : burner ? 'burner' : 'normal';
      if (burner && P.limits) S.battery = Math.max(0, S.battery - P.batteryDrain * dt);
