      const gm = inp.thrMul ?? 1;   // the gearbox's pull (its ratio, at its revs; 1 without one)
      let brakeGrip = P.brakeTurnG * Math.max(inp.brkL, inp.brkR) * smooth01((speed - P.frontBrakeV0) / (P.frontBrakeV1 - P.frontBrakeV0));
