        const aw = side * P.podAnchorW * P.podWidth / 2;
        const px = Pd.x + pc * P.podLen / 2 - ps * aw, py = Pd.y + ps * P.podLen / 2 + pc * aw;
        const dx = ex - px, dy = ey - py, d = Math.hypot(dx, dy);
        S.cables[k] = { ex, ey, px, py, f: 0, slack: d < P.cableLen };
